const db={query:async(sql:string,params:any[]=[])=>{const r=await database.query<any>(sql,params);return {rows:r.rows,rowCount:r.affectedRows};}};
let serial=Promise.resolve();function command(owner:string,operation:string,payload:any={},characterId?:string,requestId=randomUUID()):Promise<any>{const run=serial.then(async()=>{await database.exec('begin');try{const result=await handleWorld(db,owner,{operation,payload,characterId,requestId});await database.exec('commit');return result;}catch(e){await database.exec('rollback');throw e;}});serial=run.then(()=>{},()=>{});return run;}
