// Controlled database fixture aligns server time; clients cannot alter this stored challenge.
async function gatherOnline(owner:string,id:string,kind:'MINERACAO'|'PESCA',point:string,key?:string,baitId?:string) {
 const prepared=await command(owner,'world.command',{action:'beginProfessionChallenge',args:[kind,point,...(baitId?[baitId]:[])]},id);
 if(!prepared.result.success)return prepared;
 const challenge=prepared.result.challenge,row=(await db.query('select state from world_characters where id=$1',[id])).rows[0];
 row.state.professionChallenge.startsAt=Date.now()-Math.round(challenge.target*3000);
 row.state.professionChallenge.expiresAt=Date.now()+1500;
 await db.query('update world_characters set state=$2 where id=$1',[id,JSON.stringify(row.state)]);
 const receipt=await command(owner,'world.command',{action:'finishProfessionChallenge',args:[challenge.id]},id,key);return {...receipt,testChallengeId:challenge.id};
}
